class TokenBucket {
  constructor({ capacity, refillPerSecond, now = Date.now }) {
    if (typeof capacity !== 'number' || !Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || !Number.isFinite(refillPerSecond) || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative finite number');
    }
    if (typeof now !== 'function') {
      throw new RangeError('now must be a function');
    }

    this._capacity = capacity;
    this._refillPerSecond = refillPerSecond;
    this._now = now;
    this._tokens = capacity;
    this._lastRefillTime = now();
  }

  _refill() {
    const now = this._now();
    if (now < this._lastRefillTime) {
      return;
    }
    const elapsedSeconds = (now - this._lastRefillTime) / 1000;
    const addedTokens = elapsedSeconds * this._refillPerSecond;
    this._tokens = Math.min(this._capacity, this._tokens + addedTokens);
    this._lastRefillTime = now;
  }

  _validateN(n) {
    if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0 || !Number.isInteger(n)) {
      throw new RangeError('n must be a positive finite integer');
    }
  }

  tryTake(n = 1) {
    this._validateN(n);
    this._refill();
    if (this._tokens >= n) {
      this._tokens -= n;
      return true;
    }
    return false;
  }

  available() {
    this._refill();
    return this._tokens;
  }

  msUntil(n = 1) {
    this._validateN(n);
    this._refill();

    if (n > this._capacity) {
      return Infinity;
    }
    if (this._tokens >= n) {
      return 0;
    }
    if (this._refillPerSecond === 0) {
      return Infinity;
    }

    const neededTokens = n - this._tokens;
    const secondsNeeded = neededTokens / this._refillPerSecond;
    return Math.ceil(secondsNeeded * 1000);
  }
}

module.exports = { TokenBucket };

args.command:
node -e "
const { TokenBucket } = require('./kova.js');

// Test 1: Basic functionality
const bucket = new TokenBucket({ capacity: 10, refillPerSecond: 5 });
console.log('Test 1 - Initial available:', bucket.available());
console.log('Test 1 - tryTake(3):', bucket.tryTake(3));
console.log('Test 1 - available after take:', bucket.available());

// Test 2: Refill over time with fake clock
let time = 1000;
const fakeNow = () => time;
const bucket2 = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: fakeNow });
console.log('\nTest 2 - Initial:', bucket2.available());
bucket2.tryTake(10);
console.log('Test 2 - After taking 10:', bucket2.available());
time += 500; // 0.5 seconds
console.log('Test 2 - After 500ms:', bucket2.available());
time += 500; // 1 second total
console.log('Test 2 - After 1000ms:', bucket2.available());

// Test 3: msUntil
const bucket3 = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: fakeNow });
time = 1000;
bucket3.tryTake(10);
console.log('\nTest 3 - msUntil(5) when empty:', bucket3.msUntil(5));
time += 250;
console.log('Test 3 - msUntil(5) after 250ms:', bucket3.msUntil(5));
time += 250;
console.log('Test 3 - msUntil(5) after 500ms:', bucket3.msUntil(5));

// Test 4: Time going backwards
const bucket4 = new TokenBucket({ capacity: 10, refillPerSecond: 10, now: fakeNow });
time = 1000;
bucket4.tryTake(5);
console.log('\nTest 4 - Before time travel:', bucket4.available());
time = 500; // time goes backwards
console.log('Test 4 - After time travel back:', bucket4.available());
time = 1500; // time goes forward again
console.log('Test 4 - After time forward:', bucket4.available());

// Test 5: Edge cases - n > capacity
const bucket5 = new TokenBucket({ capacity: 10, refillPerSecond: 5 });
console.log('\nTest 5 - msUntil(15) > capacity:', bucket5.msUntil(15));

// Test 6: refillPerSecond = 0
const bucket6 = new TokenBucket({ capacity: 10, refillPerSecond: 0 });
bucket6.tryTake(5);
console.log('\nTest 6 - msUntil(10) with refillPerSecond=0:', bucket6.msUntil(10));

// Test 7: Validation errors
try { new TokenBucket({ capacity: 0, refillPerSecond: 1 }); } catch(e) { console.log('\nTest 7 - capacity 0:', e.message); }
try { new TokenBucket({ capacity: -1, refillPerSecond: 1 }); } catch(e) { console.log('Test 7 - capacity -1:', e.message); }
try { new TokenBucket({ capacity: NaN, refillPerSecond: 1 }); } catch(e) { console.log('Test 7 - capacity NaN:', e.message); }
try { new TokenBucket({ capacity: 10, refillPerSecond: -1 }); } catch(e) { console.log('Test 7 - refillPerSecond -1:', e.message); }
try { new TokenBucket({ capacity: 10, refillPerSecond: NaN }); } catch(e) { console.log('Test 7 - refillPerSecond NaN:', e.message); }
try { const b = new TokenBucket({ capacity: 10, refillPerSecond: 1 }); b.tryTake(0); } catch(e) { console.log('Test 7 - tryTake(0):', e.message); }
try { const b = new TokenBucket({ capacity: 10, refillPerSecond: 1 }); b.tryTake(-1); } catch(e) { console.log('Test 7 - tryTake(-1):', e.message); }
try { const b = new TokenBucket({ capacity: 10, refillPerSecond: 1 }); b.tryTake(1.5); } catch(e) { console.log('Test 7 - tryTake(1.5):', e.message); }
try { const b = new TokenBucket({ capacity: 10, refillPerSecond: 1 }); b.msUntil(0); } catch(e) { console.log('Test 7 - msUntil(0):', e.message); }

console.log('\nAll tests passed!');
"
